    raise exceptions.ConfigurationValueError(
        'Server requires chunksize to be a multiple of %d',
        self.__server_chunk_granularity)

@staticmethod
def _ArgPrinter(response, unused_upload):
  print 'Sent %s' % response.info['range']

@staticmethod
def _CompletePrinter(*unused_args):
  print 'Upload complete'

def StreamInChunks(self, callback=None, finish_callback=None,
                   additional_headers=None):
  """Send this (resumable) upload in chunks."""
  if self.strategy != _RESUMABLE_UPLOAD:
    raise exceptions.InvalidUserInputError(
        'Cannot stream non-resumable upload')
  if self.total_size is None:
    raise exceptions.InvalidUserInputError(
        'Cannot stream upload without total size')
  callback = callback or self._ArgPrinter
  finish_callback = finish_callback or self._CompletePrinter
  response = None
  self.__ValidateChunksize(self.chunksize)
  self.EnsureInitialized()
  while not self.complete:
    response = self.__SendChunk(self.stream.tell(),
                                additional_headers=additional_headers)
    if response.status_code in (httplib.OK, httplib.CREATED):
      self.__complete = True
      break
    self.__progress = self.__GetLastByte(response.info['range'])
    if self.progress + 1 != self.stream.tell():
      # TODO(craigcitro): Add a better way to recover here.
      raise exceptions.CommunicationError(
          'Failed to transfer all bytes in chunk, upload paused at byte '
          '%d' % self.progress)
    self._ExecuteCallback(callback, response)
  self._ExecuteCallback(finish_callback, response)
  return response

def __SendChunk(self, start, additional_headers=None, data=None):
  """Send the specified chunk."""
  self.EnsureInitialized()
  if data is None:
    data = self.stream.read(self.chunksize)
  end = start + len(data)

  request = http_wrapper.Request(url=self.url, http_method='PUT', body=data)
  request.headers['Content-Type'] = self.mime_type
  if data:
    request.headers['Content-Range'] = 'bytes %s-%s/%s' % (
        start, end - 1, self.total_size)
  if additional_headers:
    request.headers.update(additional_headers)

  response = http_wrapper.MakeRequest(self.bytes_http, request)
  if response.status_code not in (httplib.OK, httplib.CREATED,
                                  http_wrapper.RESUME_INCOMPLETE):
    raise exceptions.HttpError.FromResponse(response)
  if response.status_code in (httplib.OK, httplib.CREATED):
    return response
  # TODO(craigcitro): Add retries on no progress?
  last_byte = self.__GetLastByte(response.info['range'])
  if last_byte + 1 != end:
    new_start = last_byte + 1 - start
    response = self.__SendChunk(last_byte + 1, data=data[new_start:])
  return response

def NormalizeScopes(scope_spec):
  """Normalize scope_spec to a set of strings."""
  if isinstance(scope_spec, types.StringTypes):
    return set(scope_spec.split(' '))
  elif isinstance(scope_spec, collections.Iterable):
    return set(scope_spec)
  raise exceptions.TypecheckError(
      'NormalizeScopes expected string or iterable, found %s' % (
          type(scope_spec),))

def __iter__(self):
    while self.has_more_data():
        yield self.get_next_chunk()

def has_more_data(self):
    """Determines whether or not this iterator has more data to read.

    :rtype: bool
    :returns: Whether the iterator has more data or not.
    """
    if self._bytes_written == 0:
        return True
    elif not self._total_bytes:
        # self._total_bytes **should** be set by this point.
        # If it isn't, something is wrong.
        raise ValueError('Size of object is unknown.')
    else:
        return self._bytes_written < self._total_bytes

def get_headers(self):
    """Gets range header(s) for next chunk of data.

    :rtype: dict
    :returns: A dictionary of query parameters.
    """
    start = self._bytes_written
    end = self._bytes_written + self.key.CHUNK_SIZE - 1

    if self._total_bytes and end > self._total_bytes:
        end = ''

    return {'Range': 'bytes=%s-%s' % (start, end)}

def execute(self, context):

    hook = GCSHook(
        google_cloud_storage_conn_id=self.gcp_conn_id,
        delegate_to=self.delegate_to
    )

    self.log.info('Getting list of the files. Bucket: %s; Delimiter: %s; Prefix: %s',
                  self.bucket, self.delimiter, self.prefix)

    return hook.list(bucket_name=self.bucket,
                     prefix=self.prefix,
                     delimiter=self.delimiter)

def execute(self, context):
    self.log.info('Executing download: %s, %s, %s', self.bucket,
                  self.object, self.filename)
    hook = GCSHook(
        google_cloud_storage_conn_id=self.gcp_conn_id,
        delegate_to=self.delegate_to
    )

    if self.store_to_xcom_key:
        file_bytes = hook.download(bucket_name=self.bucket,
                                   object_name=self.object)
        if sys.getsizeof(file_bytes) < MAX_XCOM_SIZE:
            context['ti'].xcom_push(key=self.store_to_xcom_key, value=file_bytes)
        else:
            raise AirflowException(
                'The size of the downloaded file is too large to push to XCom!'
            )
    else:
        hook.download(bucket_name=self.bucket,
                      object_name=self.object,
                      filename=self.filename)

def execute(self, context):
    hook = GCSHook(gcp_conn_id=self.gcp_conn_id)
    hook.delete_bucket(bucket_name=self.bucket_name, force=self.force)

def _copy_single_object(self, hook, source_object, destination_object):
    if self.is_older_than:
        # Here we check if the given object is older than the given time
        # If given, last_modified_time and maximum_modified_time is ignored
        if hook.is_older_than(self.source_bucket,
                              source_object,
                              self.is_older_than
                              ):
            self.log.info("Object is older than %s seconds ago", self.is_older_than)
        else:
            self.log.debug("Object is not older than %s seconds ago", self.is_older_than)
            return
    elif self.last_modified_time and self.maximum_modified_time:
        # check to see if object was modified between last_modified_time and
        # maximum_modified_time
        if hook.is_updated_between(self.source_bucket,
                                   source_object,
                                   self.last_modified_time,
                                   self.maximum_modified_time
                                   ):
            self.log.info("Object has been modified between %s and %s",
                          self.last_modified_time, self.maximum_modified_time)
        else:
            self.log.debug("Object was not modified between %s and %s",
                           self.last_modified_time, self.maximum_modified_time)
            return

    elif self.last_modified_time is not None:
        # Check to see if object was modified after last_modified_time
        if hook.is_updated_after(self.source_bucket,
                                 source_object,
                                 self.last_modified_time):
            self.log.info("Object has been modified after %s ", self.last_modified_time)
        else:
            self.log.debug("Object was not modified after %s ", self.last_modified_time)
            return
    elif self.maximum_modified_time is not None:
        # Check to see if object was modified before maximum_modified_time
        if hook.is_updated_before(self.source_bucket,
                                  source_object,
                                  self.maximum_modified_time):
            self.log.info("Object has been modified before %s ", self.maximum_modified_time)
        else:
            self.log.debug("Object was not modified before %s ", self.maximum_modified_time)
            return

    self.log.info('Executing copy of gs://%s/%s to gs://%s/%s',
                  self.source_bucket, source_object,
                  self.destination_bucket, destination_object)

    hook.rewrite(self.source_bucket, source_object,
                 self.destination_bucket, destination_object)

    if self.move_object:
        hook.delete(self.source_bucket, source_object)

def ignore_kubernetes_files(src: str, names: List[str]) -> List[str]:
    ignored_names = []
    if src.endswith(os.path.sep + "example_dags"):
        for file_name in names:
            if "example_kubernetes" in file_name:
                ignored_names.append(file_name)
    return ignored_names

def get_source_airflow_folder() -> str:
    """
    Returns source directory for whole airflow (from the main airflow project).

    :return: the folder path
    """
    return os.path.abspath(os.path.join(dirname(__file__), os.pardir))
